#[doc(hidden)]

fn copy_from_bytes(buf: &mut &[u8], out: &mut [Self]) -> Result<bool> {

    if buf.len() < out.len() {

        return Err(Error::new(

            ErrorKind::InvalidInput,

            ERROR_UNEXPECTED_LENGTH_OF_INPUT,

        ));

    }

    let (front, rest) = buf.split_at(out.len());

    out.copy_from_slice(front);

    *buf = rest;

    Ok(true)

